package in.kabadiwala.connect.model; import org.springframework.data.annotation.*; import org.springframework.data.mongodb.core.index.*; import org.springframework.data.mongodb.core.mapping.Document; import java.time.*;
@Document("quotations") @CompoundIndex(name="lot_recycler_unique",def="{'lotId':1,'recyclerId':1}",unique=true) public class Quotation { @Id public String id; @Indexed public String lotId; @Indexed public String recyclerId; public double offeredPrice; public String priceUnit; public LocalDate proposedPickupDate; public String notes; public Instant validUntil; public String status="SUBMITTED"; @CreatedDate public Instant createdAt; }
